import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

# Generate a detailed analytics report for the supply chain system.
analytics_response = session.post(
    f"{BASE_URL}/analytics/generate",
    json={"system": "supply_chain", "report_type": "detailed"},
)
analytics_response.raise_for_status()
analytics_report = analytics_response.json()

# Retrieve all tracked aerospace components.
components_response = session.get(f"{BASE_URL}/components")
components_response.raise_for_status()
components = components_response.json()

# Delete only a component explicitly identified by the analytics report as no longer needed.
removal_ids = set()
if isinstance(analytics_report, dict):
    candidates = analytics_report.get("components_to_remove", [])
    if isinstance(candidates, list):
        for candidate in candidates:
            if isinstance(candidate, dict) and candidate.get("no_longer_needed") is True:
                component_id = candidate.get("id")
                if component_id is not None:
                    removal_ids.add(str(component_id))

if isinstance(components, list):
    for component in components:
        if not isinstance(component, dict):
            continue
        component_id = component.get("id")
        if component_id is not None and str(component_id) in removal_ids:
            delete_response = session.delete(
                f"{BASE_URL}/components/{component_id}"
            )
            delete_response.raise_for_status()

