import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
TOKEN = os.getenv("API_TOKEN")

session = requests.Session()
session.headers.update({"Accept": "application/json"})
if TOKEN:
    session.headers["Authorization"] = f"Bearer {TOKEN}"


def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", timeout=30, **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None


# Start a network-wide vulnerability scan.
scan = request("POST", "/scan/network", json={})
scan_id = scan.get("scan_id") or scan.get("id") if isinstance(scan, dict) else None

# Retrieve scan findings when the scan response provides an identifier.
scan_results = request("GET", f"/scan/{scan_id}/results") if scan_id else None

# Retrieve managed resources and select the resource identified by the scan findings.
resources = request("GET", "/infrastructure/resources") or []
resource_id = os.getenv("RESOURCE_ID")
if not resource_id and isinstance(scan_results, dict):
    resource_id = scan_results.get("resource_id")
if not resource_id and resources:
    resource_id = resources[0].get("id") or resources[0].get("resource_id")

if resource_id:
    # Update configuration parameters to address vulnerabilities, then patch
    # resource properties to optimize performance.
    request(
        "PUT",
        f"/configurations/{os.getenv('CONFIG_ID', 'vulnerability-remediation')}",
        json={
            "resource_id": resource_id,
            "parameters": {
                "vulnerability_remediation": True,
                "scan_id": scan_id,
            },
        },
    )
    request(
        "PATCH",
        f"/infrastructure/resources/{resource_id}",
        json={
            "configuration": {
                "vulnerability_remediation": True,
                "performance_optimization": True,
                "scan_id": scan_id,
            }
        },
    )

# Define a scaling policy informed by the scan outcome.
request(
    "POST",
    "/scaling/policies",
    json={
        "name": "vulnerability-response-scaling",
        "conditions": {
            "scan_id": scan_id,
            "vulnerabilities_detected": True,
        },
        "parameters": {
            "resource_id": resource_id,
            "scale_on_security_findings": True,
        },
    },
)

# Create a branch in the specified repository to track vulnerability fixes.
repository_id = os.getenv("REPOSITORY_ID")
if repository_id:
    request(
        "POST",
        f"/repositories/{repository_id}/branches",
        json={"name": "vulnerability-fixes"},
    )

# Register an application and configure access control for the remediation work.
request(
    "POST",
    "/access-control",
    json={
        "application": {
            "name": "vulnerability-remediation",
            "description": "Manage access to vulnerability findings and resource updates.",
        },
        "policies": [
            {
                "resource_id": resource_id,
                "scan_id": scan_id,
                "permissions": ["read_vulnerabilities", "update_resources"],
            }
        ],
    },
)

