    lowest_latency_region = min(regional_latencies, key=regional_latencies.get)
    insights["recommendations"].append(
        f"Prioritize latency investigation and capacity optimization in region "
        f"{highest_latency_region} ({regional_latencies[highest_latency_region]} ms); "
        f"consider routing latency-sensitive broadcasts through region "
        f"{lowest_latency_region} ({regional_latencies[lowest_latency_region]} ms) "
        f"where channel availability permits."
    )
else:
    current_ms = latency_ms(current_latency.get("latency"))
    if current_ms is not None:
        insights["recommendations"].append(
            f"Current network latency is {current_ms} ms. Compare this baseline "
            "with future regional measurements to identify latency trends."
        )
