import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

sensor_id = os.getenv("SENSOR_ID", "sensor-123")
scenario_id = os.getenv("SCENARIO_ID", "outdated-incident-scenario")
customer_ids = os.getenv("CUSTOMER_IDS", "").split(",")
customer_ids = [customer_id.strip() for customer_id in customer_ids if customer_id.strip()]

# Retrieve incident history and identify disruptions involving the specified sensor.
history_response = session.get(f"{BASE_URL}/incident-history")
history_response.raise_for_status()
incident_history = history_response.json()

def contains_sensor(value, target):
    if isinstance(value, dict):
        return any(
            contains_sensor(key, target) or contains_sensor(item, target)
            for key, item in value.items()
        )
    if isinstance(value, list):
        return any(contains_sensor(item, target) for item in value)
    return target.lower() in str(value).lower()

incidents = incident_history if isinstance(incident_history, list) else incident_history.get(
    "incidents", incident_history.get("data", [])
)
related_incidents = [
    incident for incident in incidents
    if contains_sensor(incident, sensor_id)
]

# Verify the sensor's current operational status.
sensor_response = session.get(f"{BASE_URL}/status/{sensor_id}")
sensor_response.raise_for_status()
sensor_status = sensor_response.json()

# Retrieve consumption summaries for customers affected by the matching disruptions.
consumption_trends = []
for incident in related_incidents:
    affected = incident.get("affected_customers", [])
    if isinstance(affected, list):
        incident_customer_ids = [
            str(customer.get("id", customer.get("customer_id")))
            if isinstance(customer, dict) else str(customer)
            for customer in affected
        ]
    else:
        incident_customer_ids = customer_ids

    for customer_id in incident_customer_ids:
        if not customer_id or customer_id == "None":
            continue
        response = session.get(
            f"{BASE_URL}/consumption/summary",
            params={"customer_id": customer_id},
        )
        response.raise_for_status()
        consumption_trends.append({
            "incident": incident,
            "customer_id": customer_id,
            "summary": response.json(),
        })

# Configure a peak usage alert for the affected customers.
alert_payload = {
    "customer_ids": sorted({
        item["customer_id"] for item in consumption_trends
    }),
    "sensor_id": sensor_id,
    "incident_ids": [
        str(incident.get("id"))
        for incident in related_incidents
        if incident.get("id") is not None
    ],
}
alert_response = session.post(f"{BASE_URL}/peak-alert", json=alert_payload)
alert_response.raise_for_status()

# Remove the outdated simulation scenario.
delete_response = session.delete(
    f"{BASE_URL}/scenarios/{scenario_id}"
)
delete_response.raise_for_status()

print({
    "related_incidents": related_incidents,
    "sensor_status": sensor_status,
    "consumption_trends": consumption_trends,
    "peak_alert": alert_response.json() if alert_response.content else None,
    "scenario_deleted": delete_response.status_code == 204,
})

